    let cur = start
    for (let i = 0; i < segs.length; i++) {
      const path = [...base, ...segs.slice(0, i + 1)].join('.')
      let n = cur.m.get(segs[i])
      if (!n) { n = newTable(); cur.m.set(segs[i], n) }
      if (n.t === 'table') cur = n
      else if (n.t === 'array' && n.aot) cur = n.items[n.items.length - 1]
